package Image::ExifTool::Radiance;use strict;use vars qw($VERSION);use Image::ExifTool qw(:DataAccess :Utils);$VERSION='1.02';%Image::ExifTool::Radiance::Main=(GROUPS=>{2=>'Image' },NOTES=>q{
        Information extracted from Radiance RGBE HDR images.  Tag ID's are all
        uppercase as stored in the file, but converted to lowercase by when
        extracting to avoid conflicts with internal ExifTool variables.  See
        L<http://radsite.lbl.gov/radiance/refer/filefmts.pdf> and
        L<http://www.graphics.cornell.edu/online/formats/rgbe/> for the
        specification.
    },_orient=>{Name=>'Orientation',PrintConv=>{'-Y +X'=>'Horizontal (normal)','-Y -X'=>'Mirror horizontal','+Y -X'=>'Rotate 180','+Y +X'=>'Mirror vertical','+X -Y'=>'Mirror horizontal and rotate 270 CW','+X +Y'=>'Rotate 90 CW','-X +Y'=>'Mirror horizontal and rotate 90 CW','-X -Y'=>'Rotate 270 CW',},},_command=>'Command',_comment=>'Comment',software=>'Software',view=>'View','format'=>'Format',exposure=>{Name=>'Exposure',Notes=>'divide pixel values by this to get watts/steradian/meter^2',},gamma=>'Gamma',colorcorr=>'ColorCorrection',pixaspect=>'PixelAspectRatio',primaries=>'ColorPrimaries',);sub ProcessHDR($$) {my ($et,$dirInfo)=@_;my$raf=$$dirInfo{RAF};my$buff;local $/="\x0a";return 0 unless$raf->ReadLine($buff)and $buff =~ /^#\?(RADIANCE|RGBE)\x0a/s;$et->SetFileType();my$tagTablePtr=GetTagTable('Image::ExifTool::Radiance::Main');while ($raf->ReadLine($buff)){chomp$buff;last unless length($buff)> 0 and length($buff)< 4096;if ($buff =~ s/^#\s*//){$et->HandleTag($tagTablePtr,'_comment',$buff)if length$buff;next}unless ($buff =~ /^(.*)?\s*=\s*(.*)/){$et->HandleTag($tagTablePtr,'_command',$buff)if length$buff;next}my ($tag,$val)=(lc $1,$2);my$tagInfo=$et->GetTagInfo($tagTablePtr,$tag);unless ($tagInfo){my$name=$tag;$name =~ tr/-_a-zA-Z0-9//dc;next unless length($name)> 1;$name=ucfirst$name;$tagInfo={Name=>$name };AddTagToTable($tagTablePtr,$tag,$tagInfo)}$et->FoundTag($tagInfo,$val)}if ($raf->ReadLine($buff)and $buff =~ /([-+][XY])\s*(\d+)\s*([-+][XY])\s*(\d+)/){$et->HandleTag($tagTablePtr,'_orient',"$1 $3");$et->FoundTag('ImageHeight',$2);$et->FoundTag('ImageWidth',$4)}return 1}1;